                { speaker: "熊本県建築士会宇城支部", text: "本日時点で、建築士事務所協会・建築士会ともに特段の連絡や要請等は入っていない。災害時のアスベスト（石綿）については、市町村経由で都道府県の大気汚染防止法所管部署またはボランティア担当部署（熊本県は環境生活部環境局）等からの注意喚起情報を把握することが重要。注意喚起の内容は主に、作業時の防じんマスクの適切な着用と、むやみに被災建築物等に近づかないことの2点。防じんマスクはDS2（厚生労働省規格）やN95（アメリカ規格）など捕集効率95%以上のものを。DS1は80%のため適さない。" }
