            normal: { label: "通常VCとしてニーズ受付・活動見込み", names: ["上天草市", "高森町", "南阿蘇村", "西原村", "阿蘇市", "菊陽町", "大津町"] },
            note: "熊本県社協HPに9社協（八代市、宇土市、宇城市、美里町、御船町、嘉島町、益城町、甲佐町、氷川町）のリンクを掲載している。"
