                { speaker: "中央共同募金会", text: "本日から「ボラサポ・令和8年熊本地震」助成公募を開始。まず短期と中期を行い、8月下旬から中長期の助成を行う。応募受付中で8/21締切。" },
                { speaker: "BRIDGE KUMAMOTO基金", text: "8/3 18:00から申請受付を開始していたBRIDGE KUMAMOTO基金からの助成金申請受付は、応募多数のため本日23:00で第一期の申請受付を締め切ることになった。第二期も準備している。" }
